import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`dashboard-builder`,heroTitle:`Build live dashboards in minutes`,heroSubtitle:`Perplexity Computer reviews your source data, defines the right KPIs, and builds a dashboard plan with charts, refresh logic, and decision-ready summaries.`,inputUrlCta:`Build my dashboard`,inputUrlPlaceholder:`e.g. docs.google.com/spreadsheets/... or analytics workspace URL`,inputUrlPrefill:`Go to {url} and turn it into a complete dashboard plan. (1) Analyze the source data, metrics, and business questions that matter most. (2) Define the KPI tree, calculations, and filters needed for reliable reporting. (3) Design the dashboard pages, chart choices, and drill-downs that best explain performance. (4) Recommend refresh cadence, alert thresholds, and stakeholder views. (5) Deliver a build-ready package with metric definitions, chart specs, and an executive summary.`,heroOverlaySteps:[`Reviewing the source data and the KPIs that matter most`,`Modeling calculations, filters, and reporting logic`,`Designing dashboard pages, charts, and refresh rules`,`Dashboard spec and stakeholder summary ready to share`],generatingSteps:[`Reading {url} to understand the source data, metrics, and reporting needs`,`Designing an agent to map KPI logic, filters, and data dependencies`,`Configuring dashboard views, chart recommendations, and alert thresholds`,`Packaging the work into a dashboard brief with clear implementation notes`],featureSectionTitle:`From raw metrics to decision-ready dashboards`,featureCardTitles:[`Connects to your data workflow`,`Outputs you can present`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Sheets, Airtable, BI tools, Docs, and planning systems can stay connected so the dashboard logic lands where your team already works.`,`KPI definitions. Chart specs. Drill-down logic. Refresh guidance. Computer gives your team a dashboard plan that is ready to build and review.`],capabilitySectionTitle:`Your dashboard analyst, on demand`,capabilitySectionSubtitle:`Share the source context, step away, and come back to a dashboard plan your team can trust.`,capabilityCards:[{title:`KPI Design`,description:`Computer can translate business questions into the right KPIs so your dashboards measure what the team actually needs to see.`},{title:`Data Modeling`,description:`Computer can define calculations, joins, and filters so the reporting logic stays consistent across views and teams.`},{title:`Dashboard Layout`,description:`Computer can recommend pages, chart types, drill-downs, and summaries that make the insights easier to understand at a glance.`},{title:`Connect Your Tools`,description:`Computer can package the plan for Sheets, BI tools, Docs, and planning workflows so implementation is easier to coordinate.`},{title:`Alerts and Refreshes`,description:`Computer can propose refresh cadence, anomaly thresholds, and stakeholder views so the dashboard stays useful after launch.`},{title:`Executive Summary`,description:`Computer can turn the reporting logic into a concise summary so stakeholders know what the dashboard is meant to answer.`}]});export{t as default};
